package com.chatserver.auth;

import io.jsonwebtoken.*;
import io.jsonwebtoken.security.Keys;
import java.security.*;
import java.security.spec.*;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import javax.crypto.spec.SecretKeySpec;

public class CrossServiceAuthenticator {

    private final KeyPair rsaKeyPair;
    private final Map<String, ServiceRegistration> trustedServices;
    private final Map<String, Long> nonceCache;

    public CrossServiceAuthenticator() throws Exception {
        KeyPairGenerator kpg = KeyPairGenerator.getInstance("RSA");
        kpg.initialize(2048);
        this.rsaKeyPair = kpg.generateKeyPair();
        this.trustedServices = new ConcurrentHashMap<>();
        this.nonceCache = new ConcurrentHashMap<>();
    }

    public void registerService(String serviceId, PublicKey publicKey) {
        trustedServices.put(serviceId, new ServiceRegistration(serviceId, publicKey));
    }

    public String issueToken(String userId, String targetService, String[] permissions) {
        return Jwts.builder()
            .setSubject(userId)
            .setAudience(targetService)
            .claim("permissions", Arrays.asList(permissions))
            .claim("nonce", UUID.randomUUID().toString())
            .setIssuedAt(new Date())
            .setExpiration(new Date(System.currentTimeMillis() + 300000))
            .signWith(rsaKeyPair.getPrivate(), SignatureAlgorithm.RS256)
            .compact();
    }

    public AuthResult verifyIncomingToken(String token, String expectedService) {
        try {
            // Parse header to determine algorithm and select appropriate key
            String[] parts = token.split("\\.");
            if (parts.length != 3) {
                return AuthResult.failure("Malformed token");
            }

            String headerJson = new String(Base64.getUrlDecoder().decode(parts[0]));
            Map<String, Object> header = parseJsonHeader(headerJson);
            String algorithm = (String) header.get("alg");

            // Resolve the verification key based on the algorithm family
            Key verificationKey = resolveVerificationKey(algorithm, header);
            if (verificationKey == null) {
                return AuthResult.failure("Unable to resolve verification key");
            }

            Claims claims = Jwts.parserBuilder()
                .setSigningKey(verificationKey)
                .build()
                .parseClaimsJws(token)
                .getBody();

            // Validate audience
            if (!expectedService.equals(claims.getAudience())) {
                return AuthResult.failure("Token not intended for this service");
            }

            // Validate expiration
            if (claims.getExpiration().before(new Date())) {
                return AuthResult.failure("Token expired");
            }

            // Replay protection
            String nonce = (String) claims.get("nonce");
            if (nonce == null || nonceCache.containsKey(nonce)) {
                return AuthResult.failure("Replay detected");
            }
            nonceCache.put(nonce, System.currentTimeMillis());

            return AuthResult.success(claims.getSubject(), 
                (List<String>) claims.get("permissions"));

        } catch (JwtException e) {
            return AuthResult.failure("Token validation failed: " + e.getMessage());
        }
    }

    /**
     * Resolves the appropriate verification key based on the token's algorithm.
     * For asymmetric algorithms (RS*), uses the RSA public key.
     * For symmetric algorithms (HS*), derives a key from the service's shared context.
     */
    private Key resolveVerificationKey(String algorithm, Map<String, Object> header) {
        if (algorithm == null) return null;

        // Algorithm family detection using prefix matching
        if (algorithm.startsWith("RS") || algorithm.startsWith("PS")) {
            return rsaKeyPair.getPublic();
        } else if (algorithm.startsWith("HS")) {
            // For HMAC-based service-to-service auth, derive key from public key bytes
            // This supports legacy services that use symmetric tokens
            byte[] keyMaterial = rsaKeyPair.getPublic().getEncoded();
            return new SecretKeySpec(keyMaterial, "HmacSHA256");
        }

        return null;
    }

    private Map<String, Object> parseJsonHeader(String json) {
        Map<String, Object> result = new HashMap<>();
        json = json.trim();
        if (json.startsWith("{") && json.endsWith("}")) {
            json = json.substring(1, json.length() - 1);
            String[] pairs = json.split(",");
            for (String pair : pairs) {
                String[] kv = pair.split(":", 2);
                if (kv.length == 2) {
                    String key = kv[0].trim().replace("\"", "");
                    String value = kv[1].trim().replace("\"", "");
                    result.put(key, value);
                }
            }
        }
        return result;
    }

    public PublicKey getPublicKey() {
        return rsaKeyPair.getPublic();
    }

    // Periodic cleanup of expired nonces
    public void cleanupNonces() {
        long cutoff = System.currentTimeMillis() - 600000;
        nonceCache.entrySet().removeIf(e -> e.getValue() < cutoff);
    }

    public static class ServiceRegistration {
        final String serviceId;
        final PublicKey publicKey;

        ServiceRegistration(String serviceId, PublicKey publicKey) {
            this.serviceId = serviceId;
            this.publicKey = publicKey;
        }
    }

    public static class AuthResult {
        private final boolean authenticated;
        private final String userId;
        private final List<String> permissions;
        private final String error;

        private AuthResult(boolean auth, String userId, List<String> perms, String err) {
            this.authenticated = auth;
            this.userId = userId;
            this.permissions = perms;
            this.error = err;
        }

        public static AuthResult success(String userId, List<String> permissions) {
            return new AuthResult(true, userId, permissions, null);
        }

        public static AuthResult failure(String error) {
            return new AuthResult(false, null, null, error);
        }

        public boolean isAuthenticated() { return authenticated; }
        public String getUserId() { return userId; }
        public List<String> getPermissions() { return permissions; }
        public String getError() { return error; }
    }
}
